285	  @VisibleForTesting
286	  void setMaxCapacity(float maximumCapacity) {
287	    writeLock.lock();
288	    try {
289	      // Sanity check
290	      CSQueueUtils.checkMaxCapacity(this.queuePath,
291	          queueCapacities.getCapacity(), maximumCapacity);
292	      float absMaxCapacity = CSQueueUtils.computeAbsoluteMaximumCapacity(
293	          maximumCapacity, parent);
294	      CSQueueUtils.checkAbsoluteCapacity(this.queuePath,
295	          queueCapacities.getAbsoluteCapacity(), absMaxCapacity);
296	
297	      queueCapacities.setMaximumCapacity(maximumCapacity);
298	      queueCapacities.setAbsoluteMaximumCapacity(absMaxCapacity);
299	    } finally {
300	      writeLock.unlock();
301	    }
302	  }
