401	  protected void setDynamicQueueProperties() {
402	    // Set properties from parent template
403	    if (parent instanceof ParentQueue) {
404	      ((ParentQueue) parent).getAutoCreatedQueueTemplate()
405	          .setTemplateEntriesForChild(queueContext.getConfiguration(), getQueuePath());
406	
407	      String parentTemplate = String.format("%s.%s", parent.getQueuePath(),
408	          AutoCreatedQueueTemplate.AUTO_QUEUE_TEMPLATE_PREFIX);
409	      parentTemplate = parentTemplate.substring(0, parentTemplate.lastIndexOf(
410	          DOT));
411	      Set<String> parentNodeLabels = queueContext.getQueueManager()
412	          .getConfiguredNodeLabelsForAllQueues()
413	          .getLabelsByQueue(parentTemplate);
414	
415	      if (parentNodeLabels != null && parentNodeLabels.size() > 1) {
416	        queueContext.getQueueManager()
417	            .getConfiguredNodeLabelsForAllQueues()
418	            .setLabelsByQueue(getQueuePath(), new HashSet<>(parentNodeLabels));
419	      }
420	    }
421	  }
