423	  private UserWeights getUserWeightsFromHierarchy() {
424	    UserWeights unionInheritedWeights = UserWeights.createEmpty();
425	    CSQueue parentQ = parent;
426	    if (parentQ != null) {
427	      // Inherit all of parent's userWeights
428	      unionInheritedWeights.addFrom(parentQ.getUserWeights());
429	    }
430	    // Insert this queue's userWeights, overriding parent's userWeights if
431	    // there is an overlap.
432	    unionInheritedWeights.addFrom(
433	        queueContext.getConfiguration().getAllUserWeightsForQueue(getQueuePath()));
434	    return unionInheritedWeights;
435	  }
