453	  protected void updateCapacityConfigType() {
454	    this.capacityConfigType = CapacityConfigType.NONE;
455	    for (String label : queueNodeLabelsSettings.getConfiguredNodeLabels()) {
456	      LOG.debug("capacityConfigType is '{}' for queue {}",
457	          capacityConfigType, getQueuePath());
458	
459	      CapacityConfigType localType = checkConfigTypeIsAbsoluteResource(
460	          getQueuePath(), label) ? CapacityConfigType.ABSOLUTE_RESOURCE
461	          : CapacityConfigType.PERCENTAGE;
462	
463	      if (this.capacityConfigType.equals(CapacityConfigType.NONE)) {
464	        this.capacityConfigType = localType;
465	        LOG.debug("capacityConfigType is updated as '{}' for queue {}",
466	            capacityConfigType, getQueuePath());
467	      } else {
468	        validateAbsoluteVsPercentageCapacityConfig(localType);
469	      }
470	    }
471	  }
