473	  protected void updateConfigurableResourceLimits(Resource clusterResource) {
474	    for (String label : queueNodeLabelsSettings.getConfiguredNodeLabels()) {
475	      final Resource minResource = getMinimumAbsoluteResource(getQueuePath(), label);
476	      Resource maxResource = getMaximumAbsoluteResource(getQueuePath(), label);
477	
478	      if (parent != null) {
479	        final Resource parentMax = parent.getQueueResourceQuotas()
480	            .getConfiguredMaxResource(label);
481	        validateMinResourceIsNotGreaterThanMaxResource(maxResource, parentMax, clusterResource,
482	            "Max resource configuration "
483	                + maxResource + " is greater than parents max value:"
484	                + parentMax + " in queue:" + getQueuePath());
485	
486	        // If child's max resource is not set, but its parent max resource is
487	        // set, we must set child max resource to its parent's.
488	        if (maxResource.equals(Resources.none()) &&
489	            !minResource.equals(Resources.none()) &&
490	            !parentMax.equals(Resources.none())) {
491	          maxResource = Resources.clone(parentMax);
492	        }
493	      }
494	
495	      validateMinResourceIsNotGreaterThanMaxResource(minResource, maxResource, clusterResource,
496	          "Min resource configuration "
497	              + minResource + " is greater than its max value:" + maxResource
498	              + " in queue:" + getQueuePath());
499	
500	      LOG.debug("Updating absolute resource configuration for queue:{} as"
501	              + " minResource={} and maxResource={}", getQueuePath(), minResource,
502	          maxResource);
503	
504	      usageTracker.getQueueResourceQuotas().setConfiguredMinResource(label, minResource);
505	      usageTracker.getQueueResourceQuotas().setConfiguredMaxResource(label, maxResource);
506	    }
507	  }
