509	  private void validateMinResourceIsNotGreaterThanMaxResource(Resource minResource,
510	                                                              Resource maxResource,
511	                                                              Resource clusterResource,
512	                                                              String validationError) {
513	    if (!maxResource.equals(Resources.none()) && Resources.greaterThan(
514	        resourceCalculator, clusterResource, minResource, maxResource)) {
515	      throw new IllegalArgumentException(validationError);
516	    }
517	  }
