519	  private void validateAbsoluteVsPercentageCapacityConfig(
520	      CapacityConfigType localType) {
521	    if (!queuePath.isRoot()
522	        && !this.capacityConfigType.equals(localType)) {
523	      throw new IllegalArgumentException("Queue '" + getQueuePath()
524	          + "' should use either percentage based capacity"
525	          + " configuration or absolute resource.");
526	    }
527	  }
