566	  private void initializeQueueState() {
567	    QueueState previousState = getState();
568	    QueueState configuredState = queueContext.getConfiguration()
569	        .getConfiguredState(getQueuePath());
570	    QueueState parentState = (parent == null) ? null : parent.getState();
571	
572	    // verify that we can not any value for State other than RUNNING/STOPPED
573	    if (configuredState != null && configuredState != QueueState.RUNNING
574	        && configuredState != QueueState.STOPPED) {
575	      throw new IllegalArgumentException("Invalid queue state configuration."
576	          + " We can only use RUNNING or STOPPED.");
577	    }
578	    // If we did not set state in configuration, use Running as default state
579	    QueueState defaultState = QueueState.RUNNING;
580	
581	    if (previousState == null) {
582	      // If current state of the queue is null, we would inherit the state
583	      // from its parent. If this queue does not has parent, such as root queue,
584	      // we would use the configured state.
585	      if (parentState == null) {
586	        updateQueueState((configuredState == null) ? defaultState
587	            : configuredState);
588	      } else {
589	        if (configuredState == null) {
590	          updateQueueState((parentState == QueueState.DRAINING) ?
591	              QueueState.STOPPED : parentState);
592	        } else if (configuredState == QueueState.RUNNING
593	            && parentState != QueueState.RUNNING) {
594	          throw new IllegalArgumentException(
595	              "The parent queue:" + parent.getQueuePath()
596	                  + " cannot be STOPPED as the child queue:" + getQueuePath()
597	                  + " is in RUNNING state.");
598	        } else {
599	          updateQueueState(configuredState);
600	        }
601	      }
602	    } else {
603	      // when we get a refreshQueue request from AdminService,
604	      if (previousState == QueueState.RUNNING) {
605	        if (configuredState == QueueState.STOPPED) {
606	          stopQueue();
607	        }
608	      } else {
609	        if (configuredState == QueueState.RUNNING) {
610	          try {
611	            activateQueue();
612	          } catch (YarnException ex) {
613	            throw new IllegalArgumentException(ex.getMessage());
614	          }
615	        }
616	      }
617	    }
618	  }
