620	  protected QueueInfo getQueueInfo() {
621	    // Deliberately doesn't use lock here, because this method will be invoked
622	    // from schedulerApplicationAttempt, to avoid deadlock, sacrifice
623	    // consistency here.
624	    // TODO, improve this
625	    QueueInfo queueInfo = recordFactory.newRecordInstance(QueueInfo.class);
626	    queueInfo.setQueueName(queuePath.getLeafName());
627	    queueInfo.setQueuePath(queuePath.getFullPath());
628	    queueInfo.setAccessibleNodeLabels(queueNodeLabelsSettings.getAccessibleNodeLabels());
629	    queueInfo.setCapacity(queueCapacities.getCapacity());
630	    queueInfo.setMaximumCapacity(queueCapacities.getMaximumCapacity());
631	    queueInfo.setQueueState(getState());
