792	  private Resource getCurrentLimitResource(String nodePartition,
793	      Resource clusterResource, ResourceLimits currentResourceLimits,
794	      SchedulingMode schedulingMode) {
795	    if (schedulingMode == SchedulingMode.RESPECT_PARTITION_EXCLUSIVITY) {
796	      /*
797	       * Current limit resource: For labeled resource: limit = queue-max-resource
798	       * (TODO, this part need update when we support labeled-limit) For
799	       * non-labeled resource: limit = min(queue-max-resource,
800	       * limit-set-by-parent)
801	       */
802	      Resource queueMaxResource =
803	          getQueueMaxResource(nodePartition);
804	
805	      return Resources.min(resourceCalculator, clusterResource,
806	          queueMaxResource, currentResourceLimits.getLimit());
807	    } else if (schedulingMode == SchedulingMode.IGNORE_PARTITION_EXCLUSIVITY) {
808	      // When we doing non-exclusive resource allocation, maximum capacity of
809	      // all queues on this label equals to total resource with the label.
810	      return labelManager.getResourceByLabel(nodePartition, clusterResource);
811	    }
812	
813	    return Resources.none();
814	  }
