826	  boolean canAssignToThisQueue(Resource clusterResource,
827	      String nodePartition, ResourceLimits currentResourceLimits,
828	      Resource resourceCouldBeUnreserved, SchedulingMode schedulingMode) {
829	    readLock.lock();
830	    try {
831	      // Get current limited resource:
832	      // - When doing RESPECT_PARTITION_EXCLUSIVITY allocation, we will respect
833	      // queues' max capacity.
834	      // - When doing IGNORE_PARTITION_EXCLUSIVITY allocation, we will not respect
835	      // queue's max capacity, queue's max capacity on the partition will be
836	      // considered to be 100%. Which is a queue can use all resource in the
837	      // partition.
838	      // Doing this because: for non-exclusive allocation, we make sure there's
839	      // idle resource on the partition, to avoid wastage, such resource will be
840	      // leveraged as much as we can, and preemption policy will reclaim it back
841	      // when partitioned-resource-request comes back.
842	      Resource currentLimitResource = getCurrentLimitResource(nodePartition,
843	          clusterResource, currentResourceLimits, schedulingMode);
844	
845	      Resource nowTotalUsed = usageTracker.getQueueUsage().getUsed(nodePartition);
846	
847	      // Set headroom for currentResourceLimits:
848	      // When queue is a parent queue: Headroom = limit - used + killable
849	      // When queue is a leaf queue: Headroom = limit - used (leaf queue cannot preempt itself)
850	      Resource usedExceptKillable = nowTotalUsed;
851	      if (hasChildQueues()) {
852	        usedExceptKillable = Resources.subtract(nowTotalUsed,
853	            getTotalKillableResource(nodePartition));
854	      }
855	      currentResourceLimits.setHeadroom(
856	          Resources.subtract(currentLimitResource, usedExceptKillable));
857	
858	      if (Resources.greaterThanOrEqual(resourceCalculator, clusterResource,
859	          usedExceptKillable, currentLimitResource)) {
860	
861	        // if reservation continue looking enabled, check to see if could we
862	        // potentially use this node instead of a reserved node if the application
863	        // has reserved containers.
864	        if (this.reservationsContinueLooking
865	            && Resources.greaterThan(resourceCalculator, clusterResource,
866	            resourceCouldBeUnreserved, Resources.none())) {
867	          // resource-without-reserved = used - reserved
868	          Resource newTotalWithoutReservedResource = Resources.subtract(
869	              usedExceptKillable, resourceCouldBeUnreserved);
870	
871	          // when total-used-without-reserved-resource < currentLimit, we still
872	          // have chance to allocate on this node by unreserving some containers
873	          if (Resources.lessThan(resourceCalculator, clusterResource,
874	              newTotalWithoutReservedResource, currentLimitResource)) {
875	            if (LOG.isDebugEnabled()) {
876	              LOG.debug("try to use reserved: " + getQueuePath()
877	                  + " usedResources: " + usageTracker.getQueueUsage().getUsed()
878	                  + ", clusterResources: " + clusterResource
879	                  + ", reservedResources: " + resourceCouldBeUnreserved
880	                  + ", capacity-without-reserved: "
881	                  + newTotalWithoutReservedResource
882	                  + ", maxLimitCapacity: " + currentLimitResource);
883	            }
884	            return true;
885	          }
886	        }
887	
888	        // Can not assign to this queue
889	        if (LOG.isDebugEnabled()) {
890	          LOG.debug("Failed to assign to queue: " + getQueuePath()
891	              + " nodePartition: " + nodePartition
892	              + ", usedResources: " + usageTracker.getQueueUsage().getUsed(nodePartition)
893	              + ", clusterResources: " + clusterResource
894	              + ", reservedResources: " + resourceCouldBeUnreserved
895	              + ", maxLimitCapacity: " + currentLimitResource
896	              + ", currTotalUsed:" + usedExceptKillable);
897	        }
898	        return false;
899	      }
900	      if (LOG.isDebugEnabled()) {
901	        LOG.debug("Check assign to queue: " + getQueuePath()
902	            + " nodePartition: " + nodePartition
903	            + ", usedResources: " + usageTracker.getQueueUsage().getUsed(nodePartition)
904	            + ", clusterResources: " + clusterResource
905	            + ", currentUsedCapacity: " + Resources
906	            .divide(resourceCalculator, clusterResource,
907	                usageTracker.getQueueUsage().getUsed(nodePartition), labelManager
908	                    .getResourceByLabel(nodePartition, clusterResource))
909	            + ", max-capacity: " + queueCapacities
910	            .getAbsoluteMaximumCapacity(nodePartition));
911	      }
912	      return true;
913	    } finally {
914	      readLock.unlock();
915	    }
916	
917	  }
