1045	  @Override
1046	  public boolean accept(Resource cluster,
1047	      ResourceCommitRequest<FiCaSchedulerApp, FiCaSchedulerNode> request) {
1048	    // Do we need to check parent queue before making this decision?
1049	    boolean checkParentQueue = false;
1050	
1051	    ContainerAllocationProposal<FiCaSchedulerApp, FiCaSchedulerNode> allocation =
1052	        request.getFirstAllocatedOrReservedContainer();
1053	    SchedulerContainer<FiCaSchedulerApp, FiCaSchedulerNode> schedulerContainer =
1054	        allocation.getAllocatedOrReservedContainer();
1055	
1056	    // Do not check when allocating new container from a reserved container
1057	    if (allocation.getAllocateFromReservedContainer() == null) {
1058	      Resource required = allocation.getAllocatedOrReservedResource();
1059	      Resource netAllocated = Resources.subtract(required,
1060	          request.getTotalReleasedResource());
1061	
1062	      readLock.lock();
1063	      try {
1064	        String partition = schedulerContainer.getNodePartition();
1065	        Resource maxResourceLimit;
1066	        if (allocation.getSchedulingMode()
1067	            == SchedulingMode.RESPECT_PARTITION_EXCLUSIVITY) {
1068	          maxResourceLimit = getQueueMaxResource(partition);
1069	        } else{
1070	          maxResourceLimit = labelManager.getResourceByLabel(
1071	              schedulerContainer.getNodePartition(), cluster);
1072	        }
1073	        if (!Resources.fitsIn(resourceCalculator,
1074	            Resources.add(usageTracker.getQueueUsage().getUsed(partition), netAllocated),
1075	            maxResourceLimit)) {
1076	          if (LOG.isDebugEnabled()) {
1077	            LOG.debug("Used resource=" + usageTracker.getQueueUsage().getUsed(partition)
1078	                + " exceeded maxResourceLimit of the queue ="
1079	                + maxResourceLimit);
1080	          }
1081	          return false;
1082	        }
1083	      } finally {
1084	        readLock.unlock();
1085	      }
1086	
1087	      // Only check parent queue when something new allocated or reserved.
1088	      checkParentQueue = true;
1089	    }
1090	
1091	
1092	    if (parent != null && checkParentQueue) {
1093	      return parent.accept(cluster, request);
1094	    }
1095	
1096	    return true;
1097	  }
