1211	  private Resource createNormalizedMinResource(Resource minResource,
1212	      Map<String, Float> effectiveMinRatio) {
1213	    Resource ret = Resource.newInstance(minResource);
1214	    int maxLength = ResourceUtils.getNumberOfCountableResourceTypes();
1215	    for (int i = 0; i < maxLength; i++) {
1216	      ResourceInformation nResourceInformation =
1217	          minResource.getResourceInformation(i);
1218	
1219	      Float ratio = effectiveMinRatio.get(nResourceInformation.getName());
1220	      if (ratio != null) {
1221	        ret.setResourceValue(i,
1222	            (long) (nResourceInformation.getValue() * ratio));
1223	        if (LOG.isDebugEnabled()) {
1224	          LOG.debug("Updating min resource for Queue: " + getQueuePath() + " as " + ret
1225	              .getResourceInformation(i) + ", Actual resource: "
1226	              + nResourceInformation.getValue() + ", ratio: " + ratio);
1227	        }
1228	      }
1229	    }
1230	    return ret;
1231	  }
