1233	  private Resource getOrInheritMaxResource(Resource resourceByLabel, String label) {
1234	    Resource parentMaxResource =
1235	        parent.getQueueResourceQuotas().getConfiguredMaxResource(label);
1236	    if (parentMaxResource.equals(Resources.none())) {
1237	      parentMaxResource =
1238	          parent.getQueueResourceQuotas().getEffectiveMaxResource(label);
1239	    }
1240	
1241	    Resource configuredMaxResource =
1242	        getQueueResourceQuotas().getConfiguredMaxResource(label);
1243	    if (configuredMaxResource.equals(Resources.none())) {
1244	      return Resources.clone(parentMaxResource);
1245	    }
1246	
1247	    return Resources.clone(Resources.min(resourceCalculator, resourceByLabel,
1248	        configuredMaxResource, parentMaxResource));
1249	  }
1250	
1251	  void deriveCapacityFromAbsoluteConfigurations(String label,
1252	      Resource clusterResource) {
1253	    // Update capacity with a float calculated from the parent's minResources
1254	    // and the recently changed queue minResources.
1255	    // capacity = effectiveMinResource / {parent's effectiveMinResource}
1256	    float result = resourceCalculator.divide(clusterResource,
1257	        usageTracker.getQueueResourceQuotas().getEffectiveMinResource(label),
1258	        parent.getQueueResourceQuotas().getEffectiveMinResource(label));
1259	    queueCapacities.setCapacity(label,
1260	        Float.isInfinite(result) ? 0 : result);
1261	
1262	    // Update maxCapacity with a float calculated from the parent's maxResources
1263	    // and the recently changed queue maxResources.
1264	    // maxCapacity = effectiveMaxResource / parent's effectiveMaxResource
1265	    result = resourceCalculator.divide(clusterResource,
1266	        usageTracker.getQueueResourceQuotas().getEffectiveMaxResource(label),
1267	        parent.getQueueResourceQuotas().getEffectiveMaxResource(label));
1268	    queueCapacities.setMaximumCapacity(label,
1269	        Float.isInfinite(result) ? 0 : result);
1270	
1271	    // Update absolute capacity (as in fraction of the
1272	    // whole cluster's resources) with a float calculated from the queue's
1273	    // capacity and the parent's absoluteCapacity.
1274	    // absoluteCapacity = capacity * parent's absoluteCapacity
1275	    queueCapacities.setAbsoluteCapacity(label,
1276	        queueCapacities.getCapacity(label) * parent.getQueueCapacities()
1277	            .getAbsoluteCapacity(label));
1278	
1279	    // Update absolute maxCapacity (as in fraction of the
1280	    // whole cluster's resources) with a float calculated from the queue's
1281	    // maxCapacity and the parent's absoluteMaxCapacity.
1282	    // absoluteMaxCapacity = maxCapacity * parent's absoluteMaxCapacity
1283	    queueCapacities.setAbsoluteMaximumCapacity(label,
1284	        queueCapacities.getMaximumCapacity(label) *
1285	            parent.getQueueCapacities()
1286	                .getAbsoluteMaximumCapacity(label));
1287	  }
1288	
1289	  void updateEffectiveResources(Resource clusterResource) {
1290	    for (String label : queueNodeLabelsSettings.getConfiguredNodeLabels()) {
1291	      Resource resourceByLabel = labelManager.getResourceByLabel(label,
1292	          clusterResource);
1293	      Resource newEffectiveMinResource;
1294	      Resource newEffectiveMaxResource;
1295	
1296	      // Absolute and relative/weight mode needs different handling.
1297	      if (getCapacityConfigType().equals(
1298	          CapacityConfigType.ABSOLUTE_RESOURCE)) {
1299	        newEffectiveMinResource = createNormalizedMinResource(
1300	            usageTracker.getQueueResourceQuotas().getConfiguredMinResource(label),
1301	            ((ParentQueue) parent).getEffectiveMinRatio(label));
1302	
1303	        // Max resource of a queue should be the minimum of {parent's maxResources,
1304	        // this queue's maxResources}. Both parent's maxResources and this queue's
1305	        // maxResources can be configured. If this queue's maxResources is not
1306	        // configured, inherit the value from the parent. If parent's
1307	        // maxResources is not configured its inherited value must be collected.
1308	        newEffectiveMaxResource =
1309	            getOrInheritMaxResource(resourceByLabel, label);
1310	      } else {
1311	        newEffectiveMinResource = Resources
1312	            .multiply(resourceByLabel,
1313	                queueCapacities.getAbsoluteCapacity(label));
1314	        newEffectiveMaxResource = Resources
1315	            .multiply(resourceByLabel,
1316	                queueCapacities.getAbsoluteMaximumCapacity(label));
1317	      }
1318	
1319	      // Update the effective min
1320	      usageTracker.getQueueResourceQuotas().setEffectiveMinResource(label,
1321	          newEffectiveMinResource);
1322	      usageTracker.getQueueResourceQuotas().setEffectiveMaxResource(label,
1323	          newEffectiveMaxResource);
1324	
1325	      if (LOG.isDebugEnabled()) {
1326	        LOG.debug("Updating queue:" + getQueuePath()
1327	            + " with effective minimum resource=" + newEffectiveMinResource
1328	            + "and effective maximum resource="
1329	            + newEffectiveMaxResource);
1330	      }
1331	
1332	      if (getCapacityConfigType().equals(
1333	          CapacityConfigType.ABSOLUTE_RESOURCE)) {
1334	        /*
1335	         * If the queues are configured with absolute resources, it is advised
1336	         * to update capacity/max-capacity/etc. based on the newly calculated
1337	         * resource values. These values won't be used for actual resource
1338	         * distribution, however, for accurate metrics and the UI
1339	         * they should be re-calculated.
1340	         */
1341	        deriveCapacityFromAbsoluteConfigurations(label, clusterResource);
1342	      }
1343	    }
1344	  }
