30	    29	/**
31	    30	 * This is a helper class which represents a queue path, and has easy access
32	    31	 * methods to get the path's parent or leaf part, or as a whole.
33	    32	 */
34	    33	public class QueuePath implements Iterable<String> {
35	    34	  private static final String QUEUE_REGEX_DELIMITER = "\\.";
36	    35	  /**
37	    36	   * The parent part of the queue path.
38	    37	   */
39	    38	  private String parent;
40	    39	
41	    40	  /**
42	    41	   * The leaf part of the parent path.
43	    42	   */
44	    43	  private String leaf;
45	    44	
46	    45	  /**
47	    46	   * Constructor to create mapping queue path from parent path and leaf name.
48	    47	   * @param parent Parent path of the queue
49	    48	   * @param leaf Name of the leaf queue
50	    49	   */
51	    50	  public QueuePath(String parent, String leaf) {
52	    51	    this.parent = parent;
53	    52	    this.leaf = leaf;
54	    53	  }
55	    54	
56	    55	  /**
57	    56	   * Constructor creates a MappingQueuePath object using the queue's full path.
58	    57	   * @param fullPath Full path of the queue
59	    58	   */
60	    59	  public QueuePath(String fullPath) {
61	    60	    setFromFullPath(fullPath);
62	    61	  }
63	    62	
64	    63	  /**
65	    64	   * Concatenate queue path parts into one queue path string.
66	    65	   * @param parts Parts of the full queue pathAutoCreatedQueueTemplate
67	    66	   * @return full path of the given queue parts
68	    67	   */
69	    68	  public static String concatenatePath(String... parts) {
70	    69	    return String.join(DOT, parts);
71	    70	  }
72	    71	
73	    72	  /**
74	    73	   * This method is responsible for splitting up a full queue path into parent
75	    74	   * path and leaf name.
76	    75	   * @param fullPath Full path of the queue to be processed
77	    76	   */
78	    77	  private void setFromFullPath(String fullPath) {
79	    78	    parent = null;
80	    79	    leaf = fullPath;
81	    80	
82	    81	    if (leaf == null) {
83	    82	      leaf = "";
84	    83	      return;
85	    84	    }
86	    85	
87	    86	    int lastDotIdx = fullPath.lastIndexOf(DOT);
88	    87	    if (lastDotIdx > -1) {
89	    88	      parent = fullPath.substring(0, lastDotIdx).trim();
90	    89	      leaf = fullPath.substring(lastDotIdx + 1).trim();
91	    90	    }
92	    91	  }
93	    92	
94	    93	  /**
95	    94	   * Simple helper method to determine if the path contains any empty parts.
96	    95	   * @return true if there is at least one empty part of the path
97	    96	   */
98	    97	  public boolean hasEmptyPart() {
99	    98	    for (String part : this) {
100	    99	      if (part.isEmpty()) {
101	   100	        return true;
102	   101	      }
103	   102	    }
104	   103	
105	   104	    return false;
106	   105	  }
107	   106	
108	   107	  /**
109	   108	   * Getter for the parent part of the path.
110	   109	   * @return Parent path of the queue, null if there is no parent.
111	   110	   */
112	   111	  public String getParent() {
113	   112	    return parent;
114	   113	  }
115	   114	
116	   115	  /**
117	   116	   * Getter for the leaf part of the path.
118	   117	   * @return The leaf queue name
119	   118	   */
120	   119	  public String getLeafName() {
121	   120	    return leaf;
122	   121	  }
123	   122	
124	   123	  /**
125	   124	   * Getter for the full path of the queue.
126	   125	   * @return Full path of the queue
127	   126	   */
128	   127	  public String getFullPath() {
129	   128	    return hasParent() ? (parent + DOT + leaf) : leaf;
130	   129	  }
131	   130	
132	   131	  /**
133	   132	   * Convenience getter to check if the queue has a parent path defined.
134	   133	   * @return True if there is a parent path provided
135	   134	   */
136	   135	  public boolean hasParent() {
137	   136	    return parent != null;
138	   137	  }
139	   138	
140	   139	  /**
141	   140	   * Convenience getter to check if the queue is the root queue.
142	   141	   * @return True if the path is root
143	   142	   */
144	   143	  public boolean isRoot() {
145	   144	    return !hasParent() && leaf.equals(ROOT);
146	   145	  }
147	   146	
148	   147	  /**
149	   148	   * Creates a new {@code QueuePath} from the current full path as parent, and
150	   149	   * the appended child queue path as leaf.
151	   150	   * @param childQueue path of leaf queue
152	   151	   * @return new queue path made of current full path and appended leaf path
153	   152	   */
154	   153	  public QueuePath createNewLeaf(String childQueue) {
155	   154	    return new QueuePath(getFullPath(), childQueue);
156	   155	  }
157	   156	
158	   157	  /**
159	   158	   * Returns an iterator of queue path parts, starting from the highest level
160	   159	   * (generally root).
161	   160	   * @return queue part iterator
162	   161	   */
163	   162	  @Override
164	   163	  public Iterator<String> iterator() {
165	   164	    return Arrays.asList(getFullPath().split(QUEUE_REGEX_DELIMITER)).iterator();
166	   165	  }
167	   166	
168	   167	  /**
169	   168	   * Returns an iterator that provides a way to traverse the queue path from
170	   169	   * current queue through its parents.
171	   170	   * @return queue path iterator
172	   171	   */
173	   172	  public Iterator<String> reverseIterator() {
174	   173	
175	   174	    return new Iterator<String>() {
176	   175	      private String current = getFullPath();
177	   176	
178	   177	      @Override
179	   178	      public boolean hasNext() {
180	   179	        return current != null;
181	   180	      }
182	   181	
183	   182	      @Override
184	   183	      public String next() {
185	   184	        if (!hasNext()) {
186	   185	          throw new NoSuchElementException();
187	   186	        }
188	   187	
189	   188	        int parentQueueNameEndIndex = current.lastIndexOf(".");
190	   189	        String old = current;
191	   190	        if (parentQueueNameEndIndex > -1) {
192	   191	          current = current.substring(0, parentQueueNameEndIndex).trim();
193	   192	        } else {
194	   193	          current = null;
195	   194	        }
196	   195	
197	   196	        return old;
198	   197	      }
199	   198	    };
200	   199	  }
201	   200	
202	   201	  @Override
203	   202	  public String toString() {
204	   203	    return getFullPath();
205	   204	  }
206	   205	
207	   206	  @Override
208	   207	  public boolean equals(Object o) {
209	   208	    if (this == o) {
210	   209	      return true;
211	   210	    }
212	   211	    if (o == null || getClass() != o.getClass()) {
213	   212	      return false;
214	   213	    }
215	   214	    QueuePath other = (QueuePath) o;
216	   215	    return Objects.equals(parent, other.parent) &&
217	   216	        Objects.equals(leaf, other.leaf);
218	   217	  }
219	   218	
220	   219	  @Override
221	   220	  public int hashCode() {
222	   221	    return Objects.hash(parent, leaf);
223	   222	  }
