251	    26	/**
252	    27	 * This class determines minimum and maximum allocation settings based on the
253	    28	 * {@link CapacitySchedulerConfiguration} and other queue
254	    29	 * properties.
255	    30	 **/
256	    31	public class QueueAllocationSettings {
257	    32	  private final Resource minimumAllocation;
258	    33	  private Resource maximumAllocation;
