264	    39	  void setupMaximumAllocation(CapacitySchedulerConfiguration configuration, QueuePath queuePath,
265	    40	      CSQueue parent) {
266	    41	    Resource clusterMax = ResourceUtils
267	    42	        .fetchMaximumAllocationFromConfig(configuration);
268	    43	    Resource queueMax = configuration.getQueueMaximumAllocation(queuePath);
269	    44	
270	    45	    maximumAllocation = Resources.clone(
271	    46	        parent == null ? clusterMax : parent.getMaximumAllocation());
272	    47	
273	    48	    String errMsg =
274	    49	        "Queue maximum allocation cannot be larger than the cluster setting"
275	    50	            + " for queue " + queuePath
276	    51	            + " max allocation per queue: %s"
277	    52	            + " cluster setting: " + clusterMax;
278	    53	
279	    54	    if (queueMax == Resources.none()) {
280	    55	      // Handle backward compatibility
281	    56	      long queueMemory = configuration.getQueueMaximumAllocationMb(queuePath);
282	    57	      int queueVcores = configuration.getQueueMaximumAllocationVcores(queuePath);
283	    58	      if (queueMemory != UNDEFINED) {
284	    59	        maximumAllocation.setMemorySize(queueMemory);
285	    60	      }
286	    61	
287	    62	      if (queueVcores != UNDEFINED) {
288	    63	        maximumAllocation.setVirtualCores(queueVcores);
289	    64	      }
290	    65	
291	    66	      if ((queueMemory != UNDEFINED && queueMemory > clusterMax.getMemorySize()
292	    67	          || (queueVcores != UNDEFINED
293	    68	          && queueVcores > clusterMax.getVirtualCores()))) {
294	    69	        throw new IllegalArgumentException(
295	    70	            String.format(errMsg, maximumAllocation));
296	    71	      }
297	    72	    } else {
298	    73	      // Queue level maximum-allocation can't be larger than cluster setting
299	    74	      for (ResourceInformation ri : queueMax.getResources()) {
300	    75	        if (ri.compareTo(clusterMax.getResourceInformation(ri.getName())) > 0) {
301	    76	          throw new IllegalArgumentException(String.format(errMsg, queueMax));
302	    77	        }
303	    78	
304	    79	        maximumAllocation.setResourceInformation(ri.getName(), ri);
305	    80	      }
306	    81	    }
307	    82	  }
