826	    46	  private long getInheritedMaxAppLifetime(CSQueue q, CapacitySchedulerConfiguration conf) {
827	    47	    CSQueue parentQ = q.getParent();
828	    48	    long maxAppLifetime = conf.getMaximumLifetimePerQueue(q.getQueuePathObject());
829	    49	
830	    50	    // If q is the root queue, then get max app lifetime from conf.
831	    51	    if (q.getQueuePathObject().isRoot()) {
832	    52	      return maxAppLifetime;
833	    53	    }
834	    54	
835	    55	    // If this is not the root queue, get this queue's max app lifetime
836	    56	    // from the conf. The parent's max app lifetime will be used if it's
837	    57	    // not set for this queue.
838	    58	    // A value of 0 will override the parent's value and means no max lifetime.
839	    59	    // A negative value means that the parent's max should be used.
840	    60	    long parentsMaxAppLifetime = parentQ.getMaximumApplicationLifetime();
841	    61	    return (maxAppLifetime >= 0) ? maxAppLifetime : parentsMaxAppLifetime;
