846	    66	    CSQueue parentQ = q.getParent();
847	    67	    long defaultAppLifetime = conf.getDefaultLifetimePerQueue(queuePath);
848	    68	    defaultAppLifetimeWasSpecifiedInConfig =
849	    69	        (defaultAppLifetime >= 0
850	    70	            || (!queuePath.isRoot() &&
851	    71	            parentQ.getDefaultAppLifetimeWasSpecifiedInConfig()));
