853	    73	    // If q is the root queue, then get default app lifetime from conf.
854	    74	    if (queuePath.isRoot()) {
855	    75	      return defaultAppLifetime;
856	    76	    }
857	    77	
858	    78	    // If this is not the root queue, get the parent's default app lifetime. The
859	    79	    // parent's default app lifetime will be used if not set for this queue.
860	    80	    long parentsDefaultAppLifetime = parentQ.getDefaultApplicationLifetime();
861	    81	
